-- MACHO initial schema for Cloudflare D1 (SQLite).
-- Ported from supabase/migrations (final state as of 202607080001).
-- Conventions: ids are UUID text, timestamps are ISO-8601 UTC text (same shape as Date#toISOString),
-- booleans are 0/1 integers, JSON columns are text.
-- Row ownership (formerly RLS) is enforced in src/lib/db/*: every user-data query filters by user_id.

-- Better Auth tables (generated by better-auth getMigrations for SQLite).
create table "user" ("id" text not null primary key, "name" text not null, "email" text not null unique, "emailVerified" integer not null, "image" text, "createdAt" date not null, "updatedAt" date not null);
create table "session" ("id" text not null primary key, "expiresAt" date not null, "token" text not null unique, "createdAt" date not null, "updatedAt" date not null, "ipAddress" text, "userAgent" text, "userId" text not null references "user" ("id") on delete cascade);
create table "account" ("id" text not null primary key, "accountId" text not null, "providerId" text not null, "userId" text not null references "user" ("id") on delete cascade, "accessToken" text, "refreshToken" text, "idToken" text, "accessTokenExpiresAt" date, "refreshTokenExpiresAt" date, "scope" text, "password" text, "createdAt" date not null, "updatedAt" date not null);
create table "verification" ("id" text not null primary key, "identifier" text not null, "value" text not null, "expiresAt" date not null, "createdAt" date not null, "updatedAt" date not null);
create index "session_userId_idx" on "session" ("userId");
create index "account_userId_idx" on "account" ("userId");
create index "verification_identifier_idx" on "verification" ("identifier");

-- Master data
create table muscle_groups (
  id text primary key,
  name text not null unique,
  name_en text not null,
  color text not null,
  sort_order integer not null unique
);

create table muscle_sub_groups (
  id text primary key,
  muscle_group_id text not null references muscle_groups (id) on delete restrict,
  name text not null,
  sort_order integer not null,
  unique (muscle_group_id, name),
  unique (muscle_group_id, sort_order)
);

create table equipment (
  id text primary key,
  name text not null unique,
  sort_order integer not null unique
);

-- User data
create table user_profiles (
  user_id text primary key references "user" ("id") on delete cascade,
  training_goal text check (training_goal in ('hypertrophy', 'strength', 'fat_loss', 'maintenance') or training_goal is null),
  experience_level text check (experience_level in ('beginner', 'intermediate', 'advanced') or experience_level is null),
  weekly_frequency integer check ((weekly_frequency between 1 and 7) or weekly_frequency is null),
  focus_muscle_group_ids text not null default '[]' check (json_valid(focus_muscle_group_ids) and json_type(focus_muscle_group_ids) = 'array'),
  ai_suggestion_enabled integer not null default 0,
  onboarding_completed integer not null default 0,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  subscription_tier text not null default 'free' check (subscription_tier in ('free', 'go', 'plus', 'pro')),
  stripe_customer_id text,
  subscription_status text not null default 'none' check (subscription_status in ('none', 'active', 'past_due', 'canceled')),
  subscription_id text,
  current_period_end text,
  stripe_subscription_event_created integer,
  check (onboarding_completed = 0 or (training_goal is not null and experience_level is not null and weekly_frequency is not null))
);
create unique index user_profiles_stripe_customer_id_idx on user_profiles (stripe_customer_id) where stripe_customer_id is not null;
create unique index user_profiles_subscription_id_idx on user_profiles (subscription_id) where subscription_id is not null;

create table workouts (
  id text primary key,
  user_id text not null references "user" ("id") on delete cascade,
  date text not null,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
create index workouts_user_date_idx on workouts (user_id, date desc);

create table workout_exercises (
  id text primary key,
  workout_id text not null references workouts (id) on delete cascade,
  exercise_name text not null check (length(trim(exercise_name)) between 1 and 80),
  muscle_group_id text references muscle_groups (id),
  muscle_sub_group_id text references muscle_sub_groups (id),
  equipment_id text references equipment (id),
  sort_order integer not null default 1,
  exercise_type text not null default 'strength' check (exercise_type in ('strength', 'cardio')),
  duration_minutes integer check (duration_minutes is null or duration_minutes between 1 and 1440),
  distance_km real check (distance_km is null or distance_km between 0 and 1000),
  calories integer check (calories is null or calories between 0 and 10000)
);
create index workout_exercises_workout_idx on workout_exercises (workout_id, sort_order);

create table workout_exercise_sub_groups (
  workout_exercise_id text not null references workout_exercises (id) on delete cascade,
  muscle_sub_group_id text not null references muscle_sub_groups (id) on delete restrict,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  primary key (workout_exercise_id, muscle_sub_group_id)
);
create index workout_exercise_sub_groups_sub_group_idx on workout_exercise_sub_groups (muscle_sub_group_id);

create table workout_sets (
  id text primary key,
  workout_exercise_id text not null references workout_exercises (id) on delete cascade,
  set_number integer not null check (set_number > 0),
  weight_kg real not null default 0 check (weight_kg between 0 and 1000),
  reps integer not null check (reps between 0 and 200),
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
create unique index workout_sets_exercise_set_number_uidx on workout_sets (workout_exercise_id, set_number);

create table ai_suggestion_logs (
  id text primary key,
  user_id text not null references "user" ("id") on delete cascade,
  input_hash text not null,
  request_payload text not null,
  response_payload text,
  prompt_tokens integer,
  completion_tokens integer,
  total_tokens integer,
  cost_usd real,
  status text not null check (status in ('pending', 'success', 'cached', 'rate_limited', 'forbidden', 'error')),
  error_message text,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
create index ai_suggestion_logs_input_hash_created_idx on ai_suggestion_logs (input_hash, created_at desc);
create index ai_suggestion_logs_user_created_idx on ai_suggestion_logs (user_id, created_at desc);

create table workout_templates (
  id text primary key,
  user_id text not null references "user" ("id") on delete cascade,
  name text not null,
  source text not null check (source in ('ai_suggestion', 'manual')),
  source_log_id text references ai_suggestion_logs (id) on delete set null,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
);
create index workout_templates_user_created_idx on workout_templates (user_id, created_at desc);

create table template_exercises (
  id text primary key,
  template_id text not null references workout_templates (id) on delete cascade,
  exercise_name text not null check (length(trim(exercise_name)) between 1 and 80),
  muscle_group_id text references muscle_groups (id),
  muscle_sub_group_id text references muscle_sub_groups (id),
  equipment_id text references equipment (id),
  target_sets integer check ((target_sets between 1 and 20) or target_sets is null),
  target_reps integer check ((target_reps between 1 and 200) or target_reps is null),
  target_weight_kg real check ((target_weight_kg between 0 and 1000) or target_weight_kg is null),
  notes text check (length(notes) <= 400 or notes is null),
  sort_order integer not null default 1
);
create index template_exercises_template_sort_idx on template_exercises (template_id, sort_order);

create table subscription_events (
  id text primary key,
  stripe_event_id text not null unique,
  event_type text not null,
  user_id text references "user" ("id") on delete set null,
  payload text not null,
  processed_at text,
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  processing_started_at text
);
create index subscription_events_user_created_idx on subscription_events (user_id, created_at desc);

create table api_keys (
  id text primary key,
  user_id text not null references "user" ("id") on delete cascade,
  key_hash text not null unique,
  key_prefix text not null check (length(key_prefix) = 12),
  name text not null default 'ChatGPT',
  created_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  last_used_at text
);
create index api_keys_user_created_idx on api_keys (user_id, created_at desc);

create table api_rate_limits (
  scope text not null,
  identifier text not null,
  window_start text not null,
  request_count integer not null default 0,
  updated_at text not null default (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')),
  primary key (scope, identifier, window_start)
);

-- Integrity triggers (ported from the plpgsql validate_* / enforce_* triggers).
create trigger workout_exercises_validate_insert before insert on workout_exercises
begin
  select raise(abort, 'Muscle group is required for strength exercise')
  where new.exercise_type = 'strength' and new.muscle_group_id is null;
  select raise(abort, 'Cardio exercise cannot have muscle group fields')
  where new.exercise_type = 'cardio' and (new.muscle_group_id is not null or new.muscle_sub_group_id is not null);
  select raise(abort, 'muscle_sub_group_id must belong to muscle_group_id')
  where new.muscle_sub_group_id is not null
    and (select muscle_group_id from muscle_sub_groups where id = new.muscle_sub_group_id) is not new.muscle_group_id;
end;

create trigger workout_exercises_validate_update before update on workout_exercises
begin
  select raise(abort, 'Muscle group is required for strength exercise')
  where new.exercise_type = 'strength' and new.muscle_group_id is null;
  select raise(abort, 'Cardio exercise cannot have muscle group fields')
  where new.exercise_type = 'cardio' and (new.muscle_group_id is not null or new.muscle_sub_group_id is not null);
  select raise(abort, 'muscle_sub_group_id must belong to muscle_group_id')
  where new.muscle_sub_group_id is not null
    and (select muscle_group_id from muscle_sub_groups where id = new.muscle_sub_group_id) is not new.muscle_group_id;
end;

create trigger workout_exercise_sub_groups_validate_insert before insert on workout_exercise_sub_groups
begin
  select raise(abort, 'muscle_sub_group_id must belong to the exercise muscle_group_id')
  where (select muscle_group_id from workout_exercises where id = new.workout_exercise_id) is null
    or (select muscle_group_id from muscle_sub_groups where id = new.muscle_sub_group_id)
      is not (select muscle_group_id from workout_exercises where id = new.workout_exercise_id);
end;

create trigger workout_exercise_sub_groups_validate_update before update on workout_exercise_sub_groups
begin
  select raise(abort, 'muscle_sub_group_id must belong to the exercise muscle_group_id')
  where (select muscle_group_id from workout_exercises where id = new.workout_exercise_id) is null
    or (select muscle_group_id from muscle_sub_groups where id = new.muscle_sub_group_id)
      is not (select muscle_group_id from workout_exercises where id = new.workout_exercise_id);
end;

create trigger template_exercises_validate_insert before insert on template_exercises
begin
  select raise(abort, 'muscle_group_id is required when muscle_sub_group_id is set')
  where new.muscle_sub_group_id is not null and new.muscle_group_id is null;
  select raise(abort, 'muscle_sub_group_id must belong to muscle_group_id')
  where new.muscle_sub_group_id is not null
    and (select muscle_group_id from muscle_sub_groups where id = new.muscle_sub_group_id) is not new.muscle_group_id;
end;

create trigger template_exercises_validate_update before update on template_exercises
begin
  select raise(abort, 'muscle_group_id is required when muscle_sub_group_id is set')
  where new.muscle_sub_group_id is not null and new.muscle_group_id is null;
  select raise(abort, 'muscle_sub_group_id must belong to muscle_group_id')
  where new.muscle_sub_group_id is not null
    and (select muscle_group_id from muscle_sub_groups where id = new.muscle_sub_group_id) is not new.muscle_group_id;
end;

create trigger api_keys_enforce_key_limit before insert on api_keys
begin
  select raise(abort, 'A user can have at most 5 GPT API keys')
  where (select count(*) from api_keys where user_id = new.user_id) >= 5;
end;

